#!/usr/bin/env node
/**
 * Build the interface language files from the translation sources.
 *
 *   data/registries/languages.json     the languages: codes, names, locales, what each file says
 *   data/i18n/strings/*.txt            hand-kept: one column a language, one string a line
 *   data/i18n/map-names.overlay.json   generated by build-map-name-overlay.mjs (map names)
 *        |
 *        v
 *   assets/i18n/en.json, ga.json, sco.json     key -> string, what the runtime reads
 *   assets/i18n/names.ga.json, names.sco.json  English map/catalogue name -> translation
 *   assets/i18n/languages.json                 the runtime's table of the languages
 *   data/i18n/review/*.tsv                     the lists a fluent speaker reviews
 *
 * SOURCE FORMAT (data/i18n/strings/<surface>.txt; scripts/i18n/string-files.mjs reads it)
 *
 *   #!columns en ¦ ga ¦ sco                       the header: a language code a column
 *   # a comment
 *   Add to map ¦ Cuir leis an léarscáil ¦ Pit on the map
 *   @chrome.language Language ¦ Teanga ¦ Leid
 *   Show all {n} maps ¦ Taispeáin na {n} léarscáil ar fad ¦
 *   Long paragraph of English ¦ ¦                  <- listed as untranslated in both
 *
 * The languages, their order and what each language file says about its language come from the
 * languages registry (data/registries/languages.json, packages/registries/src/languages.mjs). The
 * columns are found by the header, so a new language is a registry entry and a column in each
 * file, with no change here (acceptance test A5, tests/unit/i18n-new-language.test.mjs).
 *
 * The key is "<surface>.<slug of the English>" unless an @key is given. An empty column is a
 * missing translation: the runtime falls back to English and the review list says so. {name}
 * placeholders must appear in every translation that has the English one.
 *
 * Every translation is a DRAFT (each output file carries "_status": "draft") until a fluent
 * speaker has reviewed it; data/i18n/README.md explains how to record a review (the language's
 * reviewedBy in the registry).
 *
 * USAGE
 *   node scripts/i18n/build-i18n.mjs          write the outputs
 *   node scripts/i18n/build-i18n.mjs --check  fail if an output is out of date or a source line
 *                                             is malformed
 *   --root <dir>   read data/ and write site/ and data/i18n/review/ under <dir> instead of the
 *                  working directory (the A5 test builds a fixture tree this way); the registry is
 *                  validated against this checkout's schema either way
 */
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { languageFileStatus } from './translation-status.mjs';
import { parseStringFile } from './string-files.mjs';
import { registryErrors } from '../../packages/registries/src/index.mjs';
import { language, languageCodes, languageFileMeta, runtimeLanguages, translatedLanguages } from '../../packages/registries/src/languages.mjs';

/** @typedef {import('../../packages/registries/src/languages.mjs').LanguagesRegistry} LanguagesRegistry */
/** @typedef {import('./build-map-name-overlay.mjs').MapNameOverlay} MapNameOverlay */
/** @typedef {import('./build-map-name-overlay.mjs').MapNameRecord} MapNameRecord */

const CHECK = process.argv.includes('--check');
const rootFlag = process.argv.indexOf('--root');
const ROOT = rootFlag > 0 ? path.resolve(String(process.argv[rootFlag + 1])) : process.cwd();
const SRC_DIR = 'data/i18n/strings';
const OUT_DIR = 'site/assets/i18n';
const REVIEW_DIR = 'data/i18n/review';
const OVERLAY = 'data/i18n/map-names.overlay.json';
const REGISTRY = 'data/registries/languages.json';

/**
 * A path under ROOT.
 * @param {string} rel
 * @returns {string}
 */
const under = (rel) => path.join(ROOT, rel);

/**
 * The languages registry under ROOT, validated against the schema.
 * @returns {LanguagesRegistry}
 */
function loadLanguages() {
  /** @type {unknown} */
  const data = JSON.parse(readFileSync(under(REGISTRY), 'utf8'));
  const errors = registryErrors('languages', data);
  if (errors.length) {
    console.error(`FAIL: ${REGISTRY} is invalid:\n  ${errors.join('\n  ')}`);
    process.exit(1);
  }
  return /** @type {LanguagesRegistry} */ (data);
}

const LANGUAGES = loadLanguages();
/** The source language: every key's text and the fallback (English). */
const SOURCE = LANGUAGES.source;
/** The translated languages, in registry order. */
const LANGS = translatedLanguages(LANGUAGES);

/**
 * One source line of data/i18n/strings/<surface>.txt.
 * @typedef {object} SourceEntry
 * @property {string} key
 * @property {boolean} explicit    the line gave its own key
 * @property {string} surface      the source file's name
 * @property {string} en           the source language's text (English)
 * @property {Record<string, string>} text  translated language -> its text, '' when untranslated
 * @property {string} where        file:line, for messages
 * @property {boolean} [duplicate] the same English under the same key earlier
 */

/**
 * @param {string} text
 */
function slug(text) {
  return text.toLowerCase()
    .normalize('NFKD').replace(/[̀-ͯ]/g, '')
    .replace(/\{([a-z0-9_]+)\}/gi, '$1')
    .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '')
    .slice(0, 56) || 'x';
}

const placeholders = (/** @type {string} */ s) => [...String(s).matchAll(/\{([a-zA-Z0-9_]+)\}/g)].map((m) => m[1]).sort().join(',');

/**
 * A translated language's text of an entry ('' when untranslated).
 * @param {SourceEntry} e
 * @param {string} lang
 * @returns {string}
 */
const textOf = (e, lang) => e.text[lang] || '';

function readSources() {
  /** @type {string[]} */
  const problems = [];
  /** @type {SourceEntry[]} */
  const entries = [];
  const dir = under(SRC_DIR);
  const files = existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith('.txt')).sort() : [];
  const codes = languageCodes(LANGUAGES);
  for (const file of files) {
    const surface = path.basename(file, '.txt');
    const parsed = parseStringFile(readFileSync(path.join(dir, file), 'utf8'), { where: `${SRC_DIR}/${file}`, languages: codes, source: SOURCE });
    problems.push(...parsed.problems);
    for (const row of parsed.rows) {
      const where = `${SRC_DIR}/${file}:${row.line}`;
      const en = row.text[SOURCE] || '';
      if (!en) { problems.push(`${where}: empty English`); continue; }
      /** @type {Record<string, string>} */
      const text = {};
      for (const lang of LANGS) {
        const t = row.text[lang] || '';
        text[lang] = t;
        if (t && placeholders(t) !== placeholders(en)) problems.push(`${where}: ${lang} placeholders {${placeholders(t)}} differ from English {${placeholders(en)}}`);
      }
      entries.push({ key: row.key || `${surface}.${slug(en)}`, explicit: Boolean(row.key), surface, en, text, where });
    }
  }
  // Keys must be unique; an auto key that collides with a different English gets a hash suffix.
  /** @type {Map<string, SourceEntry>} */
  const seen = new Map();
  for (const e of entries) {
    const prior = seen.get(e.key);
    if (prior && prior.en === e.en) {
      if (LANGS.some((lang) => textOf(e, lang) && textOf(prior, lang) && textOf(e, lang) !== textOf(prior, lang))) {
        problems.push(`${e.where}: "${e.en}" is translated differently at ${prior.where}`);
      }
      e.duplicate = true;
      continue;
    }
    if (prior) {
      if (e.explicit) { problems.push(`${e.where}: key ${e.key} already used at ${prior.where}`); continue; }
      e.key = `${e.key}_${createHash('sha1').update(e.en).digest('hex').slice(0, 6)}`;
    }
    seen.set(e.key, e);
  }
  // The same English under two keys must not be translated two ways: the runtime matches
  // rendered text by its English wording and can only pick one.
  /** @type {Map<string, SourceEntry>} */
  const byEnglish = new Map();
  for (const e of entries) {
    // units.txt holds the form a noun takes after a numeral ("32 contae"), deliberately
    // different from the heading form ("Contaetha"); the runtime keeps them apart.
    if (e.duplicate || e.surface === 'units' || e.key.startsWith('months.')) continue;
    const prior = byEnglish.get(e.en);
    if (prior) {
      for (const lang of LANGS) {
        const a = textOf(e, lang);
        const b = textOf(prior, lang);
        if (a && b && a !== b) problems.push(`${e.where}: "${e.en}" (${lang}) differs from ${prior.where}: "${a}" vs "${b}"`);
      }
    } else byEnglish.set(e.en, e);
  }
  return { entries: entries.filter((e) => !e.duplicate), problems };
}

/**
 * @param {unknown} obj   a JSON document
 */
function stable(obj) {
  return `${JSON.stringify(obj, null, 1)}\n`;
}

/**
 * A map-name record's draft in `lang` ('' when it has none).
 * @param {MapNameRecord} rec
 * @param {string} lang
 * @returns {string}
 */
function draftName(rec, lang) {
  const value = /** @type {Record<string, unknown>} */ (/** @type {unknown} */ (rec))[lang];
  return typeof value === 'string' ? value : '';
}

/**
 * Counts by translated language, in registry order, after `total`.
 * @param {number} total
 * @param {(lang: string) => number} count
 * @returns {Record<string, number>}
 */
const coverageRow = (total, count) => ({ total, ...Object.fromEntries(LANGS.map((lang) => [lang, count(lang)])) });

function build() {
  const { entries, problems } = readSources();
  /** @type {Map<string, string>} */
  const outputs = new Map();
  /** @type {Record<string, Record<string, string>>} */
  const strings = { [SOURCE]: {}, ...Object.fromEntries(LANGS.map((lang) => [lang, {}])) };
  const sourceStrings = /** @type {Record<string, string>} */ (strings[SOURCE]);
  for (const e of entries) {
    sourceStrings[e.key] = e.en;
    for (const lang of LANGS) {
      const t = textOf(e, lang);
      if (t) /** @type {Record<string, string>} */ (strings[lang])[e.key] = t;
    }
  }
  const total = entries.length;
  outputs.set(`${OUT_DIR}/${SOURCE}.json`, stable({ _status: 'source', _meta: { ...languageFileMeta(LANGUAGES, SOURCE), keys: total }, strings: sourceStrings }));
  for (const lang of LANGS) {
    const meta = languageFileMeta(LANGUAGES, lang);
    const own = /** @type {Record<string, string>} */ (strings[lang]);
    // draft until the registry's reviewedBy names a reviewer (translation-status.mjs).
    const status = languageFileStatus(meta);
    outputs.set(`${OUT_DIR}/${lang}.json`, stable({
      _status: status,
      _meta: {
        ...meta, keys: Object.keys(own).length, of: total,
        note: status === 'reviewed'
          ? `Reviewed by ${meta.reviewedBy} (data/i18n/README.md).`
          : 'DRAFT: not reviewed by a fluent speaker. Not for publication until reviewed (data/i18n/README.md).'
      },
      strings: own
    }));
  }
  // The runtime's table of the languages (site/assets/i18n/i18n.js reads it first).
  outputs.set(`${OUT_DIR}/languages.json`, stable({
    _status: 'generated',
    _meta: { note: 'The interface languages, in the order the language control lists them. Generated from data/registries/languages.json by scripts/i18n/build-i18n.mjs.' },
    ...runtimeLanguages(LANGUAGES)
  }));

  // Names: map names from the generated overlay (complete translations only).
  /** @type {Partial<MapNameOverlay>} */
  const overlay = existsSync(under(OVERLAY)) ? JSON.parse(readFileSync(under(OVERLAY), 'utf8')) : { maps: {} };
  for (const lang of LANGS) {
    /** @type {Record<string, string>} */
    const names = {};
    for (const rec of Object.values(overlay.maps || {})) {
      const value = draftName(rec, lang);
      if (value && rec.en && value !== rec.en) names[rec.en] = value;
    }
    for (const rec of Object.values(overlay.extraNames || {})) {
      const value = draftName(rec, lang);
      if (value && rec.en && value !== rec.en) names[rec.en] = value;
    }
    outputs.set(`${OUT_DIR}/names.${lang}.json`, stable({
      _status: 'draft',
      _meta: { note: 'English map / catalogue name -> translation. Generated from data/i18n/map-names.overlay.json by scripts/i18n/build-i18n.mjs; DRAFT, not reviewed.', count: Object.keys(names).length },
      names: Object.fromEntries(Object.entries(names).sort(([a], [b]) => a.localeCompare(b)))
    }));
  }

  // Review lists: every translated string (for review) and every untranslated one.
  const tsv = (/** @type {string[][]} */ rows) => rows.map((r) => r.map((c) => String(c ?? '').replace(/[\t\n]/g, ' ')).join('\t')).join('\n') + '\n';
  for (const lang of LANGS) {
    const rows = [['key', 'surface', 'english', `draft_${lang}`, 'status']];
    for (const e of entries) rows.push([e.key, e.surface, e.en, textOf(e, lang), textOf(e, lang) ? 'draft - needs review' : 'UNTRANSLATED - English shown']);
    outputs.set(`${REVIEW_DIR}/strings-${lang}.tsv`, tsv(rows));
  }
  const nameRows = [['map_id', 'english', ...LANGS.map((lang) => `draft_${lang}`), 'status', 'description']];
  for (const [id, rec] of Object.entries(overlay.maps || {}).sort(([a], [b]) => a.localeCompare(b))) {
    const drafts = LANGS.map((lang) => draftName(rec, lang));
    nameRows.push([id, rec.en, ...drafts, drafts.some(Boolean) ? 'draft - needs review' : `UNTRANSLATED${rec.missing ? ` (no glossary entry: ${rec.missing.join('; ')})` : ''}`, rec.descriptionUntranslated ? 'description in English only' : '']);
  }
  outputs.set(`${REVIEW_DIR}/map-names.tsv`, tsv(nameRows));

  const summary = {
    _note: 'Generated by scripts/i18n/build-i18n.mjs. Coverage of the draft translations.',
    interfaceStrings: coverageRow(total, (lang) => Object.keys(/** @type {Record<string, string>} */ (strings[lang])).length),
    bySurface: /** @type {Record<string, Record<string, number>>} */ ({}),
    mapNames: overlay.summary || null
  };
  for (const e of entries) {
    const s = (summary.bySurface[e.surface] ||= coverageRow(0, () => 0));
    s.total = (s.total || 0) + 1;
    for (const lang of LANGS) if (textOf(e, lang)) s[lang] = (s[lang] || 0) + 1;
  }
  outputs.set(`${REVIEW_DIR}/coverage.json`, stable(summary));
  return { outputs, problems, summary };
}

const { outputs, problems, summary } = build();
if (problems.length) {
  console.error(problems.map((p) => `FAIL: ${p}`).join('\n'));
  process.exit(1);
}
/** @type {string[]} */
const stale = [];
for (const [file, content] of outputs) {
  const target = under(file);
  const current = existsSync(target) ? readFileSync(target, 'utf8').replace(/\r\n/g, '\n') : null;
  if (current === content) continue;
  if (CHECK) stale.push(file);
  else {
    mkdirSync(path.dirname(target), { recursive: true });
    writeFileSync(target, content);
  }
}
if (CHECK && stale.length) {
  console.error(`FAIL: out of date (run node scripts/i18n/build-i18n.mjs): ${stale.join(', ')}`);
  process.exit(1);
}
const s = summary.interfaceStrings;
const counts = LANGS.map((lang) => `${language(LANGUAGES, lang).englishName} ${s[lang]}`).join(', ');
console.log(`i18n: ${s.total} interface strings; ${counts}${CHECK ? ' (up to date)' : ''}.`);
